def rle_decode(s):
    """Expand run-length text: 'a3b1c12' -> 'aaab' followed by twelve c's."""
    out = []
    i = 0
    while i < len(s):
        ch = s[i]
        i += 1
        # Extract the count digits
        start = i
        while i < len(s) and s[i].isdigit():
            i += 1
        count_str = s[start:i]
        if count_str == '':
            count = 1
        else:
            count = int(count_str)
        out.append(ch * count)
    return "".join(out)
```

