def unique_paths(rows, cols):
    """Paths from the top-left to the bottom-right cell of a grid, moving only right or down."""
    # If either dimension is 0, there are no paths
    if rows == 0 or cols == 0:
        return 0

    # For a 1x1 grid, there is exactly one path (the starting cell itself)
    if rows == 1 and cols == 1:
        return 1

    # Initialize DP table
    dp = [[0] * cols for _ in range(rows)]

    # First row: only one way to reach each cell (all right moves)
    for c in range(cols):
        dp[0][c] = 1

    # First column: only one way to reach each cell (all down moves)
    for r in range(rows):
        dp[r][0] = 1

    # Fill the rest of the table
    for r in range(1, rows):
        for c in range(1, cols):
            dp[r][c] = dp[r - 1][c] + dp[r][c - 1]

    return dp[-1][-1]
```

