import report
from unittest import mock


class TestReportUsedMib(unittest.TestCase):
    """Tests for report.used_mib function."""

    @mock.patch('report.used')
    def test_used_mib_returns_correct_value(self, mock_used):
        """Test that used_mib returns the correct value when used() returns 1000 * 2.048."""
        # The requirement states that used('/data') should return 1000 * 2.048 = 2048000
        # used_mib('/data') should return 2.048
        mock_used.return_value = 2048000
        result = report.used_mib('/data')
        self.assertAlmostEqual(result, 2.048, places=5)

    @mock.patch('report.used')
    def test_used_mib_handles_zero_usage(self, mock_used):
        """Test that used_mib returns 0.0 when no space is used."""
        mock_used.return_value = 0
        result = report.used_mib('/data')
        self.assertEqual(result, 0.0)

    @mock.patch('report.used')
    def test_used_mib_handles_exact_mb(self, mock_used):
        """Test that used_mib returns correct value when usage is exactly 1000 * 2.0."""
        mock_used.return_value = 1000 * 2.0
        result = report.used_mib('/data')
        self.assertAlmostEqual(result, 2.0, places=5)

    @mock.patch('report.used')
    def test_used_mib_calls_used_with_correct_mount(self, mock_used):
        """Test that used_mib calls used() with the correct mount point."""
        mock_used.return_value = 1000 * 2.0
        report.used_mib('/data')
        mock_used.assert_called_once_with('/data')

    @mock.patch('report.used')
    def test_used_mib_calls_used_with_different_mount(self, mock_used):
        """Test that used_mib calls used() with the correct mount point for different mounts."""
        mock_used.return_value = 1000 * 2.0
        report.used_mib('/home')
        mock_used.assert_called_once_with('/home')

    @mock.patch('report.used')
    def test_used_mib_rounds_correctly(self, mock_used):
        """Test that used_mib rounds correctly for fractional MiB values."""
        # Simulate a case where used() returns a value that results in a fractional MiB
        mock_used.return_value = 1000 * 3.05  # 3050000
        result = report.used_mib('/data')
        self.assertAlmostEqual(result, 3.05, places=5)


