def parse_price(text):
    """'$1,234.50' -> 1234.5"""
    if text is None or not isinstance(text, str):
        return None

    text = text.strip()

    if not text:
        return None

    # Remove optional '$'
    if text.startswith('$'):
        text = text[1:]

    # Remove commas
    text = text.replace(',', '')

    # Strip again after removing '$' and commas
    text = text.strip()

    if not text:
        return None

    try:
        return float(text)
    except ValueError:
        return None
