import os


def rotate(path, keep):
    """Rotate a log: path -> path.1 -> path.2 ... keeping at most `keep` old copies; path starts empty."""
    # First, remove the oldest file if it exists (path.<keep>)
    # We need to shift files from highest to lowest to avoid overwriting
    for i in range(keep, 0, -1):
        src = f"{path}.{i}"
        dst = f"{path}.{i + 1}"
        if i == keep:
            # Remove the oldest if it exists since we're keeping only `keep` copies
            if os.path.exists(src):
                os.remove(src)
        else:
            if os.path.exists(src):
                os.replace(src, dst)

    # Move the current log to path.1
    if os.path.exists(path):
        os.replace(path, f"{path}.1")

    # Create an empty new log file
    open(path, "w").close()
```

